globalThis.__timing__.logStart("Load chunks/build/wedding-ring-production-time-qINKVlXo");import{_ as e}from"./GuideArticleView-CAFORXus.mjs";import{v as t,s as i,u as n}from"./server.mjs";import{b as r}from"./seo-osyWe2xM.mjs";import{c as o}from"../routes/renderer.mjs";import"./CustomCursor-SjgiEVMS.mjs";import"./nuxt-link-BM65PqDd.mjs";import"../_/nitro.mjs";import"./useGtag-SINXGlos.mjs";const a="/guide/wedding-ring-production-time",s="결혼반지 제작 기간, 촬영·예식 날짜 맞추는 주문 시점 | 귀족",p="결혼반지 제작 기간을 디자인 확정, CAD·모형, 주조, 세팅, 각인, 검수 단계로 나누고 웨딩촬영과 예식일에 맞춘 주문 일정과 지연 요인을 정리했습니다.",l="2026-07-30",d=t.defineComponent({__name:"wedding-ring-production-time",__ssrInlineRender:!0,setup(d){const g=`${i.url}/Image/guide/wedding-ring-production-time-hero.webp`,u=[{question:"결혼반지는 보통 언제 주문해야 하나요?",answer:"웨딩촬영에 착용할지부터 정한 뒤 촬영일을 첫 마감일로 잡으세요. 디자인·호수·소재가 확정된 날부터 제작 기간이 시작되는지 확인하고, 안내받은 완성 예정일 뒤에 수정과 재마감을 위한 여유 기간을 더해 주문하는 것이 안전합니다."},{question:"결혼반지 제작 기간은 왜 매장마다 다른가요?",answer:"재고품인지 주문 제작인지, 기존 디자인인지 신규 CAD가 필요한지, 보석 수급과 세팅이 있는지, 작업장이 매장 내부인지 외부인지에 따라 공정과 대기 순서가 달라집니다. 일수보다 내 반지에 포함되는 공정을 먼저 비교해야 합니다."},{question:"각인 때문에 수령일이 늦어질 수 있나요?",answer:"가능합니다. 각인은 보통 호수와 표면 마감이 끝난 뒤 진행하며 문구 재확인, 글꼴이나 특수 기호, 레이저 작업 일정에 따라 추가 시간이 필요할 수 있습니다. 각인 문구와 대소문자를 주문서에 확정해 두세요."},{question:"웨딩촬영 전까지 반지가 완성되지 않으면 어떻게 하나요?",answer:"촬영용 샘플 대여 가능 여부와 실제 반지의 예상 완성일을 바로 확인하세요. 촬영 후 본품 수령도 가능하지만 손 확대 사진이 계획돼 있다면 디자인과 색이 같은 샘플인지 먼저 확인하는 편이 좋습니다."},{question:"수령일을 앞당기려면 무엇을 먼저 정해야 하나요?",answer:"디자인, 소재와 색, 두 사람의 정확한 호수, 폭과 두께, 보석 유무, 표면 마감, 각인 문구를 한 번에 확정하면 재확인 시간을 줄일 수 있습니다. 다만 검수나 필요한 공정을 생략하는 급행 제작은 피하세요."}],m=["결혼반지 제작 기간은 결제일보다 디자인·소재·호수·각인이 모두 확정된 날짜부터 계산하는지 확인해야 정확합니다.","웨딩촬영에 반지를 착용한다면 예식일이 아니라 촬영일을 첫 마감일로 잡고, 안내받은 완성일 뒤에 수정 여유를 더하세요.","신규 디자인, 별도 보석 수급, 복잡한 세팅, 특수 각인과 성수기 작업 대기는 제작 기간을 늘리는 대표 요인입니다."],c=[{title:"제작 기간은 주문일이 아니라 사양 확정일에서 시작합니다",paragraphs:["결혼반지 상담을 시작한 날과 실제 제작이 시작되는 날은 다를 수 있습니다. 견적만 받은 상태, 샘플 디자인을 비교하는 상태, 계약금은 냈지만 호수나 각인이 미정인 상태라면 작업 지시가 확정되지 않습니다. 주문서에 디자인 번호, 소재, 색, 폭, 호수, 보석과 마감이 기록된 날짜를 기준으로 일정을 확인하세요.","매장이 말하는 제작 기간이 영업일인지 달력일인지도 구분해야 합니다. 공휴일, 작업장 휴무와 택배 이동일이 포함되는지에 따라 같은 숫자라도 실제 수령일이 달라집니다. 상담할 때는 몇 주 걸리는지보다 연도·월·일이 적힌 완성 예정일과 방문 수령 가능일을 요청하는 편이 명확합니다."],bullets:["두 사람의 최종 호수와 착용 손가락","14K·18K·백금 등 소재와 금속 색","폭·두께·표면 마감과 보석 유무","각인 문구·글꼴·대소문자","완성 예정일과 실제 수령 가능일"]},{title:"기성·주문 제작·맞춤 제작은 필요한 공정이 다릅니다",paragraphs:["진열된 완제품에 호수와 각인만 손보는 경우, 기존 모델을 원하는 소재와 호수로 새로 만드는 경우, 처음부터 디자인을 설계하는 맞춤 제작은 일정 구조가 서로 다릅니다. 겉모양이 비슷해도 새 금형이나 CAD 수정, 샘플 확인이 필요하면 제작 단계가 늘어납니다.","GIA가 소개하는 귀금속 생산 공정도 CAD와 모형 제작, 주조, 세팅, 최종 연마와 품질 검사를 별도 단계로 설명합니다. 따라서 맞춤 반지는 단순히 금속을 굳히는 시간이 아니라 각 단계의 확인과 작업 순서를 합친 기간으로 봐야 합니다."],bullets:["기성품: 재고 확인 후 호수·각인·마감 범위 확인","기존 모델 주문 제작: 소재·호수별 새 제작 여부 확인","부분 변경: 폭·보석·마감 변경이 원형에 미치는 영향 확인","완전 맞춤: 스케치·CAD·모형 승인 횟수까지 일정에 포함"],image:{src:"/Image/guide/wedding-ring-production-stages.webp",alt:"왼쪽부터 왁스 모형, 거친 주조품, 연마된 금반지, 보석이 세팅된 완성 반지 네 개",caption:"모형 제작부터 주조, 연마와 세팅까지 포함되는 단계가 많을수록 승인과 검수 일정도 함께 확인해야 합니다."}},{title:"웨딩촬영일을 첫 마감일로 두고 역산하세요",paragraphs:["스튜디오 촬영에서 손을 잡거나 부케 위에 손을 올리는 장면을 계획했다면 반지가 필요한 첫날은 예식일보다 빠릅니다. 촬영용으로 실제 반지를 쓸지, 매장 샘플을 대여할지 먼저 결정한 뒤 수령일을 정하세요. 촬영 전날 수령 일정은 호수가 맞지 않거나 표면 마감이 기대와 다를 때 대응하기 어렵습니다.","실무적으로는 주문처가 확정한 제작 기간에 수령 후 착용 확인, 한 차례 수정 가능성, 공휴일과 이동일을 별도 여유로 더하는 방식이 안전합니다. 예식 직전에 주문해야 한다면 가능한 디자인을 먼저 좁히고, 급행 가능 여부보다 어떤 공정을 생략하지 않는지를 확인하세요."],bullets:["1차 마감일: 웨딩촬영 또는 프로포즈 날짜","2차 마감일: 본식 전 최종 착용 확인 날짜","수정 여유: 호수·각인·표면 재마감 가능성","이동 여유: 공휴일·택배·방문 예약 일정"]},{title:"보석 수급과 디자인 변경이 가장 큰 일정 변수입니다",paragraphs:["특정 크기와 등급의 다이아몬드나 유색보석을 별도로 찾는다면 반지 본체보다 보석 수급이 먼저 끝나야 할 수 있습니다. 세팅 높이와 난집 크기는 실제 보석 치수에 맞춰야 하므로 비슷한 캐럿이라는 이유로 바로 대체할 수 없는 경우도 있습니다.","제작 중 폭, 색, 보석 개수나 각인 문구를 바꾸면 이미 만든 CAD·모형·주조품을 수정하거나 다시 제작해야 할 수 있습니다. 변경 가능 기한, 추가 비용과 완성일 변동을 구두로만 듣지 말고 주문서나 메시지로 남겨야 두 사람과 매장이 같은 기준으로 일정을 관리할 수 있습니다."],bullets:["별도 주문 보석의 입고 예정일","CAD 또는 모형 승인 횟수","제작 시작 후 변경 가능한 항목","변경 시 추가 비용과 새 완성 예정일"]},{title:"호수·각인·표면 마감은 수령 전 함께 검수합니다",paragraphs:["완성 연락을 받으면 두 사람이 직접 착용해 손가락 마디를 통과하는지, 손을 내렸을 때 빠질 정도로 헐겁지 않은지 확인하세요. GIA는 손가락 굵기가 온도와 시간대 등에 따라 달라질 수 있다고 설명하므로 한 번의 느낌만으로 급하게 호수를 바꾸기보다 착용 손과 반지 폭을 함께 확인해야 합니다.","안쪽 각인은 철자와 날짜, 대소문자, 방향을 주문서와 대조하고 유광·무광·헤어라인 같은 표면 마감이 샘플과 같은지도 봅니다. 보석이 있다면 흔들림, 발의 걸림과 좌우 균형을 확인하고 두 반지의 색과 폭이 주문 내용대로인지 나란히 비교하세요."],bullets:["착용 손·호수·넓은 반지의 압박감","각인 철자·날짜·방향","유광·무광 등 표면 마감","보석 흔들림·세팅 발·좌우 균형","두 반지의 소재·색·폭 대조"]},{title:"상담에서는 기간보다 날짜와 책임 범위를 기록하세요",paragraphs:["제작 기간을 비교할 때 가장 짧은 답만 고르면 공정 범위가 다른 견적을 같은 조건으로 보게 됩니다. 상담일에 디자인 확정일, 제작 시작일, 중간 승인일, 완성 예정일과 수령일을 한 줄 일정표로 적고 지연이 생기면 언제 안내받는지 확인하세요.","완성 후 호수 조정, 각인 수정이나 표면 재마감이 필요할 때 추가 기간과 비용이 어떻게 적용되는지도 중요합니다. 보증 범위와 무상·유상 기준, 촬영용 샘플 대여 여부까지 함께 기록하면 결혼반지 제작 기간을 단순한 숫자가 아니라 실제 행사 일정에 맞춰 관리할 수 있습니다."],bullets:["제작 기간의 시작일과 영업일 기준","확정된 완성일·수령일·지연 안내 방식","호수·각인·마감 수정 기간과 비용","촬영용 샘플 대여 조건","수령 후 보증과 AS 접수 방법"]}],w=["웨딩반지 제작 기간은 디자인과 작업장 일정에 따라 달라지므로 온라인의 평균 일수를 계약 납기로 보지 마세요.","성수기 급행 제작은 가능 여부만 보지 말고 세팅, 연마와 최종 검수 공정이 모두 포함되는지 확인하세요.","완성 예정일은 구두 표현보다 연도·월·일로 기록하고 촬영일과 예식일 사이에 수정 여유를 두세요."],y=[{to:"/guide/wedding-jewelry-set-composition",label:"결혼예물 세트 구성",description:"신랑·신부·혼주 예물 준비 순서"},{to:"/guide/wedding-band-matte-gloss",label:"웨딩밴드 무광 유광",description:"표면 마감과 재마감 기준"},{to:"/guide/ring-size-measuring-method",label:"반지 사이즈 재는 법",description:"주문 전 정확한 호수 측정"}];return n({title:s,link:[{rel:"canonical",href:`${i.url}${a}`}],meta:[{name:"description",content:p},{property:"og:title",content:s},{property:"og:description",content:p},{property:"og:type",content:"article"},{property:"og:url",content:`${i.url}${a}`},{property:"og:image",content:g},{property:"og:locale",content:"ko_KR"},{name:"twitter:card",content:"summary_large_image"},{name:"twitter:title",content:s},{name:"twitter:description",content:p},{name:"twitter:image",content:g}],script:[{type:"application/ld+json",innerHTML:JSON.stringify(r([{name:"홈",path:"/"},{name:"귀금속 가이드",path:"/guide"},{name:"결혼반지 제작 기간",path:a}]))},{type:"application/ld+json",innerHTML:JSON.stringify({"@context":"https://schema.org","@type":"Article",headline:s,description:p,image:g,datePublished:l,dateModified:l,mainEntityOfPage:`${i.url}${a}`,author:{"@type":"Organization",name:i.name,url:i.url},publisher:{"@type":"Organization",name:i.name,url:i.url}})},{type:"application/ld+json",innerHTML:JSON.stringify({"@context":"https://schema.org","@type":"FAQPage",mainEntity:u.map(e=>({"@type":"Question",name:e.question,acceptedAnswer:{"@type":"Answer",text:e.answer}}))})}]}),(i,n,r,a)=>{n(o(e,t.mergeProps({category:"기간",keyword:"결혼반지 제작 기간","inquiry-type":"custom","inquiry-topic":"결혼반지 제작 일정",title:"결혼반지 제작 기간, 촬영·예식 날짜 맞추는 주문 시점",lead:"결혼반지 제작 기간은 주문한 날보다 디자인·소재·호수·각인이 확정된 날부터 확인해야 정확합니다. 웨딩촬영과 예식일에 맞춰 공정을 역산하는 방법, 일정이 늘어나는 조건과 수령 전 검수 항목을 정리했습니다.","published-at":l,"hero-image":"/Image/guide/wedding-ring-production-time-hero.webp","hero-alt":"결혼반지 두 개와 캘리퍼 한 개, 빈 달력 한 장","quick-answers":m,sections:c,cautions:w,"faq-items":u,"related-links":y},a),null,r))}}}),g=d.setup;d.setup=(e,i)=>{const n=t.useSSRContext();return(n.modules||(n.modules=new Set)).add("pages/guide/wedding-ring-production-time.vue"),g?g(e,i):void 0};export{d as default};globalThis.__timing__.logEnd("Load chunks/build/wedding-ring-production-time-qINKVlXo");
